import{_ as e,c as a,o,ag as r}from"./chunks/framework._xRlcm3f.js";const p=JSON.parse('{"title":"本地系统配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/fs-local-system.md","filePath":"platforms/fs-local-system.md","lastUpdated":1790228279000}'),d={name:"platforms/fs-local-system.md"};function s(l,t,n,i,c,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="本地系统配置指南" tabindex="-1">本地系统配置指南 <a class="header-anchor" href="#本地系统配置指南" aria-label="Permalink to &quot;本地系统配置指南&quot;">​</a></h1><p>把文档导出为 Markdown 到本地文件系统，附带静态站点 Front Matter（YAML）。仅在桌面端（Electron）环境可用。</p><h2 id="一、适用场景" tabindex="-1">一、适用场景 <a class="header-anchor" href="#一、适用场景" aria-label="Permalink to &quot;一、适用场景&quot;">​</a></h2><ul><li>把思源文档批量导出为 Markdown，供 Hexo / Hugo / Jekyll / VuePress / VitePress 等静态站点使用。</li><li>仅 Electron 桌面环境可用（需访问本机文件路径）。</li></ul><h2 id="二、配置" tabindex="-1">二、配置 <a class="header-anchor" href="#二、配置" aria-label="Permalink to &quot;二、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>存储路径</td><td>Markdown 写入位置，默认 <code>下载目录/syp</code>，可含 <code>[auto]</code>（发布时替换为文章分类名）</td></tr><tr><td>媒体存储路径</td><td>图片、附件相对文章目录的保存位置，默认 <code>assets</code></td></tr><tr><td>YAML 类型</td><td>默认 / Hexo / Hugo / Jekyll / Vuepress / Vuepress2 / Vitepress / Quartz / Astro；选具体框架时按该框架的 Front Matter 输出</td></tr><tr><td>发布格式</td><td>默认 Markdown；目标流程要求 HTML 时才改</td></tr><tr><td>图床服务</td><td>默认「当前平台」：图片写入配置的媒体目录；也可选「PicGo 强烈推荐」用你配置的 PicGo；「不使用」跳过图片处理、按原图地址引用</td></tr></tbody></table><h2 id="三、发布" tabindex="-1">三、发布 <a class="header-anchor" href="#三、发布" aria-label="Permalink to &quot;三、发布&quot;">​</a></h2><p>快速发布 → 选本地系统 → 发布，文档会导出到配置的输出目录。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>为什么只有桌面环境可用</strong>：需要访问本机文件路径，浏览器环境不可用。</li><li><strong>图片存哪</strong>：默认在文章目录下的 <code>assets</code> 子目录；实际路径随输出目录与 <code>[auto]</code> 的解析结果变化。</li><li><strong>YAML 类型选哪个</strong>：按后续消费 Markdown 的静态站点框架选；不确定就保持默认。</li><li><strong>按分类分文件夹</strong>：输出目录里写 <code>[auto]</code>，例如 <code>下载目录/syp/[auto]</code>，发布时替换成该文章的分类名。</li></ul>',10)])])}const m=e(d,[["render",s]]);export{p as __pageData,m as default};
